#include <iostream>
#include <iomanip>
#include <string>

class GradeBook {
public:
    explicit GradeBook(std::string name) {
        setCourseName(name);
    }

    void setCourseName(std::string name) {
        if (name.size() <= 25) {
            courseName = name;
        } else {
            courseName = name.substr(0, 25);
            std::cerr << "Name \"" << name << "\" exceeds maximum length (25).\n"
                      << "Limiting courseName to first 25 characters.\n";
        }
    }

    std::string getCourseName() const {
        return courseName;
    }

    void displayMessage() const {
        std::cout << "Welcome to the grade book for\n" << getCourseName() << "!\n\n";
    }

    void determineClassAverage() const {
        int total{0};
        unsigned int gradeCounter{0};

        std::cout << "Enter grade or -1 to quit: ";
        int grade{0};
        std::cin >> grade;

        while (grade != -1) {
            total += grade;
            gradeCounter += 1;

            std::cout << "Enter grade or -1 to quit: ";
            std::cin >> grade;
        }

        if (gradeCounter != 0) {
            double average = static_cast<double>(total) / gradeCounter;
            std::cout << "\nTotal of all " << gradeCounter << " grades entered is " << total << "\n";
            std::cout << std::fixed << std::setprecision(2);
            std::cout << "Class average is " << average << "\n";
        } else {
            std::cout << "No grades were entered\n";
        }
    }

private:
    std::string courseName;
};

int main() {
    GradeBook myGradeBook("CS101 C++ Programming");
    myGradeBook.displayMessage();
    myGradeBook.determineClassAverage();
    return 0;
}
